llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C42"],
      "claim": "In healthy human male volunteers, a 10 mg oral solution of cilomilast in the fasted state had a mean absolute bioavailability of 96% (range 92–102%) versus IV infusion, directly supporting F ≥ 20%."
    },
    {
      "card_ids": ["C20"],
      "claim": "In healthy adult volunteers, oral tranexamic acid at a 2 g dose had a systemic availability of 33.4%, an affirmative threshold-relevant measurement above 20%."
    },
    {
      "card_ids": ["C25"],
      "claim": "In patients, oral pentazocine 100 mg (2 x 50 mg tablets) had a measured oral bioavailability of 18%, below the 20% threshold; this is the main contradictory evidence."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C25"],
  "decision_summary": "Multiple high-transfer absolute human bioavailability records support F ≥ 20%, including values of 96%, 91%, 80–100%, 90–95%, 36%, and 33.4%. The only consistent low-F evidence is pentazocine at 18%, which is outweighed by the positive evidence.",
  "evidence_gaps": [
    "The low-F direction rests on a single molecule (pentazocine); no other retrieved molecules had F < 20%.",
    "One pentazocine record in cirrhosis reported higher systemic availability, but it is an altered-condition measurement and was not used."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C42", "C20"],
  "revision_action": "initial",
  "supportive_card_ids": ["C42", "C20"]
}

